import React from 'react';

import { SymbolAtom } from '../../../tooltip-atoms/components/SymbolAtom.js';
import { EmojiShape } from '../../../tooltip-atoms/shapes/EmojiShape.js';
import { TooltipEmojiProps } from '../../types/ChartTooltip.config.js';

export const TooltipEmoji = (props: TooltipEmojiProps) => {
  const { children, active = false, label, ...rest } = props;

  return (
    <SymbolAtom {...rest}>
      <EmojiShape active={active} label={label}>
        {children}
      </EmojiShape>
    </SymbolAtom>
  );
};

TooltipEmoji['displayName'] = 'TooltipEmoji';
